  "\u041B\u041E\u041A\u0410\u041B\u042C\u041D\u042B\u0419 \u041F\u0420\u041E\u0422\u041E\u0422\u0418\u041F \xB7 07": "LOCAL PROTOTYPE \xB7 07",
