  "\u041E\u0442\u0432\u0435\u0442\u044C \u043F\u043E\u043A\u0443\u043F\u0430\u0442\u0435\u043B\u044E \u043D\u0430 \u043E\u0442\u0437\u044B\u0432 \u043E \u0447\u0430\u0439\u043D\u0438\u043A\u0435.": "Reply to the customer's review of the kettle.",
  "\u0427\u0438\u0442\u0430\u0442\u044C \u043E\u0442\u0437\u044B\u0432\u044B \u0438 \u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u0442\u044C \u043E\u0442\u0432\u0435\u0442\u044B. \u0418\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435 \u0442\u043E\u0432\u0430\u0440\u043E\u0432 \u0438 \u0444\u0438\u043D\u0430\u043D\u0441\u043E\u0432\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u043D\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u044B.": "Read reviews and publish replies. Product changes and financial actions are not allowed.",
  "\u041E\u0442\u0432\u0435\u0442 \u043F\u043E\u043A\u0443\u043F\u0430\u0442\u0435\u043B\u044E \u2014 \u043F\u043E \u0434\u0435\u043B\u0443.": "A reply that stays on task.",
  "\u0410\u0433\u0435\u043D\u0442 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u0438\u043B \u043E\u0442\u0432\u0435\u0442 \u0438 \u043F\u0440\u043E\u0441\u0438\u0442 \u043E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u0442\u044C \u0435\u0433\u043E \u043F\u043E\u0434 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u043C \u043E\u0442\u0437\u044B\u0432\u043E\u043C.": "The agent has prepared a reply and requests permission to publish it under the selected review.",
  "\u041E\u0442\u0432\u0435\u0442 \u043D\u0430 \u043E\u0442\u0437\u044B\u0432 \u2116 42": "Reply to review #42",
