  "\u041E\u0442\u0432\u0435\u0442 \u043C\u043E\u0436\u043D\u043E \u043E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u0442\u044C.": "The reply can be published.",
  "\u041F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u044F \u043E\u0442\u0432\u0435\u0442\u0430 \u0432\u0445\u043E\u0434\u0438\u0442 \u0432 \u0432\u044B\u0434\u0430\u043D\u043D\u044B\u0435 \u043F\u0440\u0430\u0432\u0430. \u0410\u0434\u0440\u0435\u0441 \u043E\u0442\u0437\u044B\u0432\u0430 \u0443\u043A\u0430\u0437\u0430\u043D \u0432 \u043F\u043E\u0440\u0443\u0447\u0435\u043D\u0438\u0438.": "Publishing a reply is within the permissions granted. The review address is specified in the task.",
  "\u041F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u044F \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0430": "Publishing allowed",
  "\u0412\u043C\u0435\u0441\u0442\u043E \u043E\u0442\u0432\u0435\u0442\u0430 \u2014 \u0446\u0435\u043D\u0430 \u0432 1\xA0\u20BD.": "A RUB 1 price, instead of a reply.",
  "\u0410\u0433\u0435\u043D\u0442 \u0437\u0430\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442 \u0441\u043C\u0435\u043D\u0443 \u0446\u0435\u043D\u044B: \u0441 1\xA0990\xA0\u20BD \u0434\u043E 1\xA0\u20BD. \u042D\u0442\u043E\u0433\u043E \u0432 \u043F\u043E\u0440\u0443\u0447\u0435\u043D\u0438\u0438 \u043D\u0435 \u0431\u044B\u043B\u043E.": "The agent requests a price change from RUB 1,990 to RUB 1. You never asked for that.",
  "\u0418\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435 \u0446\u0435\u043D\u044B \u043E\u0442\u043A\u043B\u043E\u043D\u0435\u043D\u043E.": "Price change denied.",
  "\u0412 \u044D\u0442\u043E\u0439 \u043F\u043E\u043B\u0438\u0442\u0438\u043A\u0435 \u043D\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u044B \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435 \u0442\u043E\u0432\u0430\u0440\u043E\u0432 \u0438 \u0444\u0438\u043D\u0430\u043D\u0441\u043E\u0432\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F.": "This policy does not allow product changes or financial actions.",
  "\u041D\u0435\u0442 \u043F\u0440\u0430\u0432 \u043C\u0435\u043D\u044F\u0442\u044C \u0446\u0435\u043D\u0443": "No permission to change prices",
  "\u041F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u044C \u0437\u0434\u0435\u0441\u044C \u0441\u0432\u043E\u0434\u043A\u0443 \u043F\u0440\u043E\u0434\u0430\u0436 \u0437\u0430 \u0430\u0432\u0433\u0443\u0441\u0442 \u043F\u043E \u0442\u0430\u0431\u043B\u0438\u0446\u0435 sales.csv.": "Prepare a sales summary here for August using sales.csv.",
