  "\u0421\u0432\u043E\u0434\u043A\u0430 \u0432 \u0447\u0430\u0442\u0435": "Summary in chat",
  "\u041F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0430 \u0441\u0432\u043E\u0434\u043A\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0430.": "Summary allowed.",
  "\u0421\u0432\u043E\u0434\u043A\u0430 \u0432\u0445\u043E\u0434\u0438\u0442 \u0432 \u043F\u0440\u0430\u0432\u0430 \u0430\u0433\u0435\u043D\u0442\u0430. \u0414\u0430\u043D\u043D\u044B\u0435 \u043D\u0435 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0432\u043D\u0435\u0448\u043D\u0435\u043C\u0443 \u043F\u043E\u043B\u0443\u0447\u0430\u0442\u0435\u043B\u044E.": "Summarizing is within the agent's permissions. No data is sent to an outside recipient.",
